[SPOILER="Инструкция"][B]Закинуть файлы на сайт

Выполнить запросы в базу:[/B]
[PHP]CREATE TABLE IF NOT EXISTS `bb_order` (
  `id` int(11) unsigned NOT NULL auto_increment,
  `forum_id` int(11) NOT NULL default '0',
  `topic_id` int(11) NOT NULL default '0',
  `user_id` int(11) NOT NULL default '0',
  `poster_id` int(11) NOT NULL default '0',
  `title` varchar(200) NOT NULL,
  `description` text,
  `time` int(11) NOT NULL default '0',
  `vote` int(11) NOT NULL default '0',
  PRIMARY KEY  (`id`)
) ENGINE=MyISAM  DEFAULT CHARSET=utf8;
CREATE TABLE IF NOT EXISTS `bb_order_vote` (
  `id` int(11) NOT NULL default '0',
  `user_id` int(11) NOT NULL default '0',
  KEY  (`id`)
) ENGINE=MyISAM  DEFAULT CHARSET=utf8;[/PHP]

[B]Открыть library/includes/functions.php

Найти[/B]

[PHP]$all_forums_option = null)[/PHP]

[B]Заменить на[/B]

[PHP]$all_forums_option = null, $tor_f = false)[/PHP]

[B]Найти[/B]

[PHP]foreach ($forums['f'] as $fid => $f)
{
[/PHP]
[B]Заменить на[/B]

[PHP]foreach ($forums[(($tor_f) ? 'forum' : 'f')] as $fid => $f)
{
   if($tor_f && !$f['allow_reg_tracker']) continue;
[/PHP]
[B]Найти[/B]

[PHP]function generate_pagination ($base_url, $num_items, $per_page, $start_item, $add_prevnext_text = TRUE)[/PHP]

[B]Заменить на[/B]

[PHP]function generate_pagination ($base_url, $num_items, $per_page, $start_item, $add_prevnext_text = TRUE, $prifix = '&amp;')[/PHP]

[B]Найти все значения[/B]

[PHP]"&amp;start="[/PHP]

[B]Заменить на[/B]

[PHP]$prifix ."start="[/PHP]

[B]Открыть library/ajax/index_data.php[/B]

[B]Найти[/B]

[PHP]}

$this->response['html'] = $html;
$this->response['mode'] = $mode;
[/PHP]
[B]Выше вставить[/B]
[PHP]
   case 'order_vote':

     global $bb_cfg, $userdata, $lang;

     $id = (int) $this->request['id'];

     if(!DB()->fetch_row("SELECT * FROM bb_order_vote WHERE id = '". $id ."' AND user_id = ". $userdata['user_id'])) {
       if(DB()->query("INSERT INTO bb_order_vote (id, user_id) VALUES ('". DB()->escape($id) ."', '". $userdata['user_id'] ."')")) {
         if(DB()->query("UPDATE bb_order SET vote = vote + '1' WHERE id = ".$id)) $this->ajax_die($lang['ORDER_THANKS']);
       }
       else $this->ajax_die($lang['ERROR']);
     } else $this->ajax_die($lang['ORDER_VOTE_ERROR']);

   break;
[/PHP]
